import 'android.graphics.*'

function random(...)
  math.randomseed(tonumber(string.reverse(os.clock()))*100000)
  return math.random(...)
end


local W=activity.Width
local H=activity.Height
local bmp=Bitmap.createBitmap(W,H,Bitmap.Config.RGB_565)
local g=Canvas(bmp)
local pen=Paint()
local w=W/24
local m=23
local x=1
local y=1
local rect={}
local _rect={}
local n=4
rect[1]=Rect(w,w,w,w)
_rect[1]={x=1,y=1}

function p()
  X= random (0,m)
  Y= random (0,m)
  _Rect=Rect(X*w,Y*w,(X+1)*w-1,(Y+1)*w-1)
end

p()
local f=0
local m_x=0
local m_y=0
function tick()
  g=holder.lockCanvas()

  --如果画布尚未创建
  if not g then
    return
  end

  --如果超过屏幕
  x=x+m_x
  y=y+m_y
  if x>m then
    x=0
   elseif x<0 then
    x=m
   elseif y>m then
    y=0
   elseif y<0 then
    y=m
  end

  --移动蛇体位置
  local rectangle=Rect(x*w,y*w,(x+1)*w-1,(y+1)*w-1)
  table.insert (rect,1,rectangle)
  table.insert (_rect,1,{x=x,y=y})
  rect[n+1]= nil
  _rect[n+1]= nil

  --如果遇到食物
  if x==X and y==Y then
    n=n+1
    p()
    f=f+10
    tm.Interval=math.max(tm.Interval-2,20)
    activity.Title= '得分：' ..f
  end

  --如果遇到自己
  recth=_rect[1]
  for r=5,#rect do
    if recth.x==_rect[r].x and recth.y==_rect[r].y then
      n=r
      rect[n]=nil
      f=0
      activity.Title= '得分：' ..f
     elseif n<r then
      rect[r]=nil
    end
  end

  --绘制蛇和食物
  g.drawColor(0xffffffff)
  for k,rectangle in ipairs (rect) do
    g.drawRect(rectangle,pen)
  end
  g.drawRect(_Rect,pen)
  g.drawLine(0,W,W,W,pen)
  holder.unlockCanvasAndPost(ca)
end

tm=Ticker()
tm.Interval=200
tm.Enabled= true
tm.onTick=tick

function up()
  if st~='d' then
    m_x,m_y=0,-1
    st='u'
  end
end

function down()
  if st~='u' then
    m_x,m_y=0,1
    st='d'
  end
end

function left()
  if st~='r' then
    m_x,m_y=-1,0
    st='l'
  end
end

function right()
  if st~='l' then
    m_x,m_y=1,0
    st='r'
  end
end


callback=SurfaceHolder.Callback{
  surfaceChanged=function(holder,format,width,height)
  end,
  surfaceCreated=function(holder)
    ca=holder.lockCanvas()

    --如果没有启动定时器则启动
    if not tm.isRun() then
      tm.start()
      right()
    end
    holder.unlockCanvasAndPost(ca)
  end,
  surfaceDestroyed=function(holder)
  end
}
holder=sureface.getHolder()
holder.addCallback(callback)

function onStart()
  tm.Enabled=true
end

function onStop()
  tm.Enabled=false
end

