//根据名字查询平均成绩，输入参数，输出参数
create proc pxs_avgByName(
@name char(8) ,@avg float output
)
as
set @avg=(select avg(成绩) 
from xs,xs_kc 
where xs.学号=xs_kc.学号 
and xs.姓名=@name)
