//如果在XS表中添加或修改的学生学号不是以“08”开头，
//则使用RAISERROR语句向客户端显示一条信息“学号必修以08开头”。
create trigger tri_n
on xs
for insert,update
as 
declare @i char(6)
select @i=学号 from inserted
if @i not like '08%'
begin
ROLLBACK TRANSACTION 
RAISERROR ('学号必修以08开头，操作已经撤消！', 16, 10)
end
