function YLua:获取屏幕尺寸()
  import "android.util.DisplayMetrics"
  local dm = DisplayMetrics();
  activity.getWindowManager().getDefaultDisplay().getMetrics(dm);
  diagonalPixels = Math.sqrt(Math.pow(dm.widthPixels, 2) + Math.pow(dm.heightPixels, 2));
  return diagonalPixels / (160 * dm.density);
end

function YLua:获取手机内置存储剩余空间()
  fs = StatFs(Environment.getDataDirectory().getPath())
  return 格式化文件大小(fs.getAvailableBytes())
end

function YLua:获取手机内置存储空间()
  path = Environment.getExternalStorageDirectory()
  stat = StatFs(path.getPath())
  blockSize = stat.getBlockSize()
  totalBlocks = stat.getBlockCount()
  return 格式化文件大小(blockSize * totalBlocks)
end

function YLua:解压缩(压缩路径,解压缩路径)
  xpcall(function()
    ZipUtil.unzip(压缩路径,解压缩路径)
  end,function()
    print("解压文件 "..压缩路径.." 失败")
  end)
end

function YLua:压缩(原路径,压缩路径,名称)
  xpcall(function()
    LuaUtil.zip(原路径,压缩路径,名称)
  end,function()
    print("压缩文件 "..原路径.." 至 "..压缩路径.."/"..名称.." 失败")
  end)
end

function YLua:重命名文件(旧,新)
  import "java.io.File"
  xpcall(function()
    File(旧).renameTo(File(新))
  end,function()
    print("重命名文件 "..旧.." 失败")
  end)
end

function YLua:移动文件(旧,新)
  import "java.io.File"
  xpcall(function()
    File(旧).renameTo(File(新))
  end,function()
    print("移动文件 "..旧.." 至 "..新.." 失败")
  end)
end

function YLua:文件修改时间(path)
  import "java.io.File"
  f = File(path);
  time = f.lastModified()
  return time
end

function YLua:内置存储路径(t)
  return Environment.getExternalStorageDirectory().toString().."/"..t
end

function YLua:获取视频第一帧(path)
  import "android.media.MediaMetadataRetriever"
  media = MediaMetadataRetriever()
  media.setDataSource(tostring(path))
  return media.getFrameAtTime()
end

function YLua:px2dp(pxValue)
  local scale = this.getResources().getDisplayMetrics().density
  return (pxValue / scale + 0.5)
end

function YLua:dp2px(dpValue)
  local scale = this.getResources().getDisplayMetrics().density
  return (dpValue * scale + 0.5)
end

function YLua:sp2px(spValue)
  local fontScale = this.getResources().getDisplayMetrics().scaledDensity
  return (spValue * fontScale + 0.5)
end

function YLua:全屏()
  activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN)
end

function YLua:退出全屏()
  activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN)
end

function YLua:复制文本(文本)
  activity.getSystemService(Context.CLIPBOARD_SERVICE).setText(文本)
end




